import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Goftego: Realtime Chat, One Command Away","description":"The story of building Goftego — a self-hosted chat platform with realtime channels, presence and typing indicators in one SQLite file.","frontmatter":{"title":"Goftego: Realtime Chat, One Command Away","description":"The story of building Goftego — a self-hosted chat platform with realtime channels, presence and typing indicators in one SQLite file."},"headers":[],"relativePath":"en/vibe-stories/story-4/index.md","filePath":"en/vibe-stories/story-4/index.md"}`),a={name:`en/vibe-stories/story-4/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="goftego-realtime-chat-one-command-away" tabindex="-1">Goftego: Realtime Chat, One Command Away <a class="header-anchor" href="#goftego-realtime-chat-one-command-away" aria-label="Permalink to “Goftego: Realtime Chat, One Command Away”">​</a></h1><p>Hosted chat SaaS locks your community behind someone else&#39;s storage, pricing and jurisdiction. For small teams that just want a room, the trade is absurd: your conversations, their database. <strong>Goftego</strong> (<a href="https://github.com/Godde3s/goftego" target="_blank" rel="noreferrer">GitHub</a>) — <em>goftego</em> means &quot;conversation&quot; — is my answer: a modern chat platform you host yourself, in one command.</p><h2 id="the-one-file-bet" tabindex="-1">The one-file bet <a class="header-anchor" href="#the-one-file-bet" aria-label="Permalink to “The one-file bet”">​</a></h2><p>The whole state of a deployment lives in <strong>one SQLite file</strong> with WAL mode. No database server to babysit, no external services to trust. Backup is <code>cp</code>; migration is moving the file. That single constraint shaped everything else: it forced efficient queries, careful transaction design, and a deploy story that is literally <code>docker compose up</code>.</p><h2 id="realtime-is-a-product-feature-not-a-checkbox" tabindex="-1">Realtime is a product feature, not a checkbox <a class="header-anchor" href="#realtime-is-a-product-feature-not-a-checkbox" aria-label="Permalink to “Realtime is a product feature, not a checkbox”">​</a></h2><ul><li><strong>WebSocket fan-out</strong> — channel messages land on every subscriber without polling, with presence counts and typing indicators that make the room feel alive.</li><li><strong>Auth that respects the data</strong> — bcrypt (cost 12) password hashing and JWT sessions, because &quot;self-hosted&quot; must not mean &quot;insecure&quot;.</li><li><strong>A UI for humans</strong> — a Vue 3 SPA, dark by default, bilingual Persian/English with proper RTL. For a Persian-speaking team, an interface that reads right is not a nice-to-have.</li></ul><h2 id="what-it-proves" tabindex="-1">What it proves <a class="header-anchor" href="#what-it-proves" aria-label="Permalink to “What it proves”">​</a></h2><p>Goftego is full-stack product work: realtime protocol design on the backend, state management on the frontend, and an opinionated data model underneath. It shows I can take a product from &quot;wouldn&#39;t it be nice&quot; to <code>docker compose up</code> — and that I treat self-hosted users with the same security bar as a public SaaS. Your community&#39;s data stays on your box, where it belongs.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};